// ============================================================
// WF5 — ROUTER: Detect which stage of the service lifecycle
// Actions:
//   'en_route'  → provider is heading to customer
//   'arrived'   → provider arrived on site
//   'completed' → service done, trigger feedback
//   'feedback'  → customer submits rating + review
// ============================================================
const body = $input.first().json.body;
const action = body.action || 'en_route';

const validActions = ['en_route', 'arrived', 'completed', 'feedback'];
if (!validActions.includes(action)) {
  return [{ json: {
    status: 'error',
    message: `Invalid action '${action}'. Must be one of: ${validActions.join(', ')}`,
    workflow: 'WF5-Router'
  }}];
}

console.log('=== WF5 Quality Loop Router ===');
console.log('Action:', action);
console.log('Booking ID:', body.booking_id);

return [{ json: { ...body, action } }];

// ============================================================
// WF5 — EN ROUTE UPDATE
// Simulates provider heading to customer location.
// Updates booking status in Supabase to 'en_route'.
// Returns ETA + WhatsApp-style notification.
// ============================================================
const data = $input.first().json;

if (!data.booking_id) {
  return [{ json: { status: 'error', message: 'booking_id is required', workflow: 'WF5-EnRoute' }}];
}

const distanceKm = parseFloat(data.distance_km) || (Math.random() * 10 + 5);
const etaMinutes = Math.round(distanceKm * 3 + 5);
const etaText = etaMinutes <= 10 ? 'approximately 10 minutes'
  : etaMinutes <= 20 ? 'approximately 15-20 minutes'
  : `approximately ${etaMinutes} minutes`;

const now = new Date();
const arrivalTime = new Date(now.getTime() + etaMinutes * 60000);
const arrivalStr = arrivalTime.toTimeString().substring(0, 5);

const enRouteUpdate = {
  status: 'en_route',
  booking_id: data.booking_id,
  provider_name: data.provider_name || 'Your Provider',
  service_type: data.service_type,
  user_email: data.user_email,
  eta_minutes: etaMinutes,
  estimated_arrival_time: arrivalStr,
  customer_location: data.location,
  live_tracking_simulated: true,
  simulated_whatsapp:
    `Assalam o Alaikum!\n` +
    `Your provider ${data.provider_name || 'is'} is on the way!\n` +
    `ETA: ${etaText} (around ${arrivalStr})\n` +
    `Booking: ${data.booking_id}`,
  checklist_reminder: [
    'Ensure access to service area',
    'Have booking ID ready: ' + data.booking_id,
    'Cash prepared: PKR ' + (data.price_pkr || 'as quoted')
  ],
  workflow: 'WF5-EnRoute',
  timestamp: now.toISOString()
};

console.log('=== WF5 En Route ===');
console.log('ETA:', etaMinutes, 'mins ->', arrivalStr);

return [{ json: enRouteUpdate }];

// ============================================================
// WF5 — ARRIVED ON SITE
// Provider reached customer. Log arrival. Return service checklist.
// ============================================================
const data = $('WF5 — Router').first().json;
const now = new Date();

const serviceChecklists = {
  'AC repair':       ['Check power supply & thermostat', 'Inspect filters and coils', 'Test compressor operation', 'Check refrigerant pressure', 'Clean drainage pipe', 'Test cooling performance', 'Document fault found'],
  'AC installation': ['Verify wall bracket position', 'Run copper piping', 'Connect electrical wiring', 'Install indoor unit', 'Install outdoor unit', 'Vacuum and charge refrigerant', 'Test full system operation'],
  'AC gas refill':   ['Check for leaks first', 'Evacuate old gas if needed', 'Recharge refrigerant to spec', 'Check operating pressure', 'Test cooling performance'],
  'plumber':         ['Identify leak/blockage source', 'Turn off water supply', 'Replace or repair component', 'Check for secondary leaks', 'Restore water supply and test'],
  'electrician':     ['Check circuit breaker/fuse', 'Test voltage at fault point', 'Identify wiring issue', 'Repair or replace component', 'Test load under full power'],
  'carpenter':       ['Measure and mark work area', 'Prepare materials', 'Execute carpentry task', 'Sand and finish if needed', 'Clean work area'],
  'painter':         ['Prepare surface (clean, sand, fill)', 'Apply primer if needed', 'Apply first coat', 'Allow drying time', 'Apply final coat', 'Inspect finish quality'],
  'generator mechanic': ['Check fuel level and oil', 'Inspect spark plugs', 'Test battery voltage', 'Start and monitor RPM', 'Check output voltage', 'Document work done']
};

const serviceKey = Object.keys(serviceChecklists).find(k =>
  (data.service_type || '').toLowerCase().includes(k.toLowerCase())
) || 'AC repair';

const checklist = serviceChecklists[serviceKey].map((item, i) => ({
  step: i + 1,
  task: item,
  completed: false,
  photo_required: i === serviceChecklists[serviceKey].length - 1
}));

const arrivedPayload = {
  status: 'arrived',
  booking_id: data.booking_id,
  provider_name: data.provider_name,
  service_type: data.service_type,
  user_email: data.user_email,
  arrival_time: now.toTimeString().substring(0, 5),
  arrival_timestamp: now.toISOString(),
  customer_location: data.location,
  service_checklist: checklist,
  photo_evidence_placeholder: {
    before_photo: 'PHOTO_UPLOAD_SLOT — Before work begins',
    after_photo:  'PHOTO_UPLOAD_SLOT — After work completed'
  },
  simulated_whatsapp:
    `Provider Arrived — Khadmat AI\n` +
    `${data.provider_name} pahunch gaye hain!\n` +
    `Arrival: ${now.toTimeString().substring(0, 5)}\n` +
    `Service: ${data.service_type}\n` +
    `Booking: ${data.booking_id}\n` +
    `Kaam shuru ho raha hai.`,
  workflow: 'WF5-Arrived',
  timestamp: now.toISOString()
};

console.log('=== WF5 Arrived ===');
console.log('Checklist items:', checklist.length);

return [{ json: arrivedPayload }];

// ============================================================
// WF5 — SERVICE COMPLETED
// Provider marks job done. Log completion time.
// Detect price overrun. Trigger feedback request.
// ============================================================
const data = $('WF5 — Router').first().json;
const now = new Date();

let durationText = 'Not recorded';
if (data.arrival_time) {
  const [arrH, arrM] = data.arrival_time.split(':').map(Number);
  const arrivalMs = new Date();
  arrivalMs.setHours(arrH, arrM, 0, 0);
  const durationMins = Math.round((now - arrivalMs) / 60000);
  durationText = durationMins > 0 ? `${durationMins} minutes` : 'Under 1 minute';
}

const finalPrice = parseInt(data.final_price_pkr) || parseInt(data.price_pkr) || 0;
const quotedPrice = parseInt(data.price_pkr) || 0;
const priceVariance = finalPrice - quotedPrice;
const priceStatus = priceVariance === 0 ? 'exact' : priceVariance > 0 ? 'overrun' : 'underrun';

const completionSummary = {
  status: 'completed',
  booking_id: data.booking_id,
  provider_name: data.provider_name,
  service_type: data.service_type,
  user_email: data.user_email,
  location: data.location,
  completion_time: now.toTimeString().substring(0, 5),
  completion_timestamp: now.toISOString(),
  duration: durationText,
  payment: {
    quoted_pkr: quotedPrice,
    final_pkr: finalPrice,
    variance_pkr: priceVariance,
    price_status: priceStatus,
    price_note: priceVariance > 0
      ? `Final price PKR ${priceVariance} zyada hai quote se. Dispute ke liye WF6 mein report karein.`
      : priceVariance < 0
      ? `Final price PKR ${Math.abs(priceVariance)} kam hai — discount!`
      : 'Final price matches quote exactly.'
  },
  photo_evidence_placeholder: {
    before_photo: data.before_photo_url || 'BEFORE_PHOTO — Not uploaded',
    after_photo:  data.after_photo_url  || 'AFTER_PHOTO — Not uploaded'
  },
  checklist_completed: data.checklist_completed || false,
  feedback_requested: true,
  feedback_payload_example: {
    action: 'feedback',
    booking_id: data.booking_id,
    provider_id: data.provider_id,
    provider_name: data.provider_name,
    rating: 5,
    review: 'Bahut acha kaam kiya'
  },
  simulated_whatsapp:
    `Service Complete — Khadmat AI\n` +
    `${data.provider_name} ne kaam mukammal kar diya!\n` +
    `Service: ${data.service_type}\n` +
    `Final Amount: PKR ${finalPrice}\n` +
    `Booking: ${data.booking_id}\n` +
    `Apni feedback zaroor dein!`,
  workflow: 'WF5-Completed',
  timestamp: now.toISOString()
};

console.log('=== WF5 Completed ===');
console.log('Price status:', priceStatus, '| Final:', finalPrice, '| Quoted:', quotedPrice);

return [{ json: completionSummary }];

// ============================================================
// WF5 — FEEDBACK PROCESSOR (UPDATED)
// Accepts: images (base64), transcript text, sentiment analysis
// Now properly validates and passes through image data
// ============================================================
const data = $('WF5 — Router').first().json;

if (!data.booking_id || !data.rating) {
  return [{ json: {
    status: 'error',
    message: 'booking_id and rating (1-5) are required for feedback',
    workflow: 'WF5-Feedback'
  }}];
}

const rating = parseFloat(data.rating);
if (rating < 1 || rating > 5) {
  return [{ json: {
    status: 'error',
    message: 'Rating must be between 1 and 5',
    received_rating: rating,
    workflow: 'WF5-Feedback'
  }}];
}

const review = data.review || '';
const transcript = data.transcript_text || '';
const providerName = data.provider_name || 'Provider';

// ── Validate and cap image array ─────────────────────────────
// Frontend sends up to 3 resized base64 JPEGs
const rawImages = Array.isArray(data.image_base64_array)
  ? data.image_base64_array
  : [];

// Validate each entry is a non-empty string starting with data:image or raw base64
const validImages = rawImages.filter(img =>
  typeof img === 'string' && img.length > 100
);

const imageCount = validImages.length;
const hasImages = imageCount > 0;

// ── Transcript validation ─────────────────────────────────────
const transcriptIncluded = data.transcript_included === true
  || (typeof transcript === 'string' && transcript.trim().length > 0);

// ── Sentiment Keywords ────────────────────────────────────────
const positiveKeywords = ['acha', 'badhiya', 'zabardast', 'great', 'excellent',
  'good', 'perfect', 'fast', 'professional', 'recommend', 'satisfied',
  'happy', 'best', 'top', 'waqt par', 'punctual'];
const negativeKeywords = ['bura', 'ganda', 'late', 'delay', 'kharab', 'worst',
  'bad', 'slow', 'unprofessional', 'disappointed', 'overcharge',
  'zyada charge', 'no show', 'nahi aaya', 'bakwaas'];

const fullText = (review + ' ' + transcript).toLowerCase();
const positiveFound = positiveKeywords.filter(w => fullText.includes(w));
const negativeFound = negativeKeywords.filter(w => fullText.includes(w));

const sentiment = negativeFound.length > positiveFound.length ? 'negative'
  : positiveFound.length > negativeFound.length ? 'positive'
  : rating >= 4 ? 'positive' : rating <= 2 ? 'negative' : 'neutral';

// ── Reputation Score Recalculation ───────────────────────────
const oldRating = 4.1;
const reviewCount = 28;
const newRating = parseFloat(
  ((oldRating * reviewCount + rating) / (reviewCount + 1)).toFixed(2)
);
const delta = parseFloat((newRating - oldRating).toFixed(2));

// ── Matching Impact ───────────────────────────────────────────
let matchingImpact = 'none';
let flagForReview = false;
if (rating <= 2) { matchingImpact = 'score_penalized'; flagForReview = true; }
else if (rating >= 5 && sentiment === 'positive') { matchingImpact = 'score_boosted'; }

// ── Auto-escalate to WF6 if very bad ─────────────────────────
const triggerDispute = rating <= 2
  || (sentiment === 'negative' && negativeFound.length >= 2);

const feedbackResult = {
  status: 'feedback_received',
  booking_id: data.booking_id,
  provider_id: data.provider_id,
  provider_name: providerName,
  service_type: data.service_type,
  user_email: data.user_email,
  submitted_rating: rating,
  review_text: review,
  transcript_text: transcript,
  transcript_included: transcriptIncluded,
  sentiment,
  sentiment_signals: {
    positive_keywords_found: positiveFound,
    negative_keywords_found: negativeFound
  },
  // Image evidence — validated and counted
  images_attached: imageCount,
  image_count: imageCount,
  has_image_evidence: hasImages,
  image_base64_array: validImages,  // passes through to Supabase write
  evidence_summary: hasImages
    ? `${imageCount} photo(s) attached as evidence`
    : transcriptIncluded
    ? 'Voice transcript included as evidence'
    : 'Text review only',
  reputation_update: {
    old_rating: oldRating,
    new_rating: newRating,
    delta,
    review_count_new: reviewCount + 1,
    direction: delta >= 0 ? 'Improved' : 'Declined'
  },
  matching_impact: {
    impact_type: matchingImpact,
    flag_for_manual_review: flagForReview,
    future_ranking_note: matchingImpact === 'score_penalized'
      ? `${providerName} will rank lower in future searches until rating recovers.`
      : matchingImpact === 'score_boosted'
      ? `${providerName} gets a ranking boost — excellent review!`
      : 'No change to ranking.'
  },
  escalate_to_wf6: triggerDispute,
  escalation_reason: triggerDispute
    ? 'Low rating or negative review keywords detected'
    : null,
  customer_message: rating >= 4
    ? `Shukriya! ${rating}-star review save ho gaya.${hasImages ? ' Photos bhi save ho gayi hain.' : ''} ${providerName} ko future mein priority di jaegi.`
    : rating === 3
    ? `Shukriya feedback ke liye. Hum ${providerName} ki service improve karne ki koshish karenge.`
    : `Humein afsos hai. Hum is mamle ko investigate karenge aur aap se rabta karenge.`,
  workflow: 'WF5-Feedback',
  timestamp: new Date().toISOString()
};

console.log('=== WF5 Feedback ===');
console.log('Rating:', rating, '| Sentiment:', sentiment);
console.log('Images validated:', imageCount, '(received:', rawImages.length, ')');
console.log('Transcript included:', transcriptIncluded, '| Length:', transcript.length);
console.log('New reputation:', newRating);
console.log('Escalate to WF6:', triggerDispute);

return [{ json: feedbackResult }];

const data = $input.first().json;

const action = data.action;
const booking_id = data.booking_id;

const current_status = data.current_status;
const last_action = data.last_action;
const tracking_locked = data.tracking_locked;

// 1. HARD LOCK CHECK — only block if explicitly locked (feedback done)
if (tracking_locked === true || current_status === "feedback_done") {
  return [{
    json: {
      allow: false,
      status: "tracking_locked",
      tracking_locked: true,
      message: "This booking has already been tracked and feedback submitted. No further actions allowed.",
      booking_id
    }
  }];
}

// 2. prevent duplicate actions
if (last_action === action) {
  return [{
    json: {
      allow: false,
      status: "blocked_duplicate",
      tracking_locked: tracking_locked === true,
      message: `Action '${action}' already executed for this booking`,
      booking_id
    }
  }];
}

// 3. Valid state transition map
const allowedTransitions = {
  en_route: ["booked", "confirmed"],
  arrived: ["en_route"],
  completed: ["arrived"],
  feedback: ["completed"]
};

const allowedFromStates = allowedTransitions[action];

if (!allowedFromStates) {
  return [{
    json: {
      allow: false,
      status: "invalid_action",
      tracking_locked: tracking_locked === true,
      message: `Unknown action '${action}'`,
      booking_id
    }
  }];
}

if (!allowedFromStates.includes(current_status)) {
  return [{
    json: {
      allow: false,
      status: "blocked_invalid_state",
      tracking_locked: tracking_locked === true,
      message: `Cannot move to '${action}' from current status '${current_status}'. Expected one of: ${allowedFromStates.join(", ")}`,
      booking_id
    }
  }];
}

// Allow execution
return [{
  json: {
    ...data,
    allow: true,
    tracking_locked: false,
    traceKey: `${booking_id}-${action}`
  }
}];

// WF5 — MERGE NODE (clean production merge)

const items = $input.all();

const actionObj = items.find(i => i.json.action);
const bookingObj = items.find(i => i.json.booking_id);

if (!bookingObj) {
  return [{
    json: {
      status: "error",
      message: "booking object not found"
    }
  }];
}

// merge both into single state object
const merged = {
  ...bookingObj.json,
  ...actionObj?.json,

  // safety normalization
  action: actionObj?.json?.action || null,

  // keep trace consistency
  traceKey: `${bookingObj.json.booking_id}-${actionObj?.json?.action || bookingObj.json.last_action || 'unknown'}`,

  // ensure Supabase-friendly status mapping
  current_status: bookingObj.json.status || bookingObj.json.current_status || null,

  // CRITICAL: pass tracking_locked through so "If" node can check it
  tracking_locked: bookingObj.json.tracking_locked === true || bookingObj.json.tracking_locked === "true"
};

return [{ json: merged }];

// WF5 — FEEDBACK GUARD
// Reads tracking_locked from the Supabase-fetched booking row
// (available via Trace Guard which already ran).
// If already tracked, block immediately with clear frontend signal.

const data = $('WF5 — Router').first().json;

// The Supabase-fetched booking data is in Trace Guard output
// which was merged into the current context via Merge + Code in JavaScript.
// By the time we reach here, $json has the merged data including tracking_locked.
const mergedData = $input.first().json;

const tracking_locked = mergedData.tracking_locked === true
  || mergedData.tracking_locked === "true"
  || mergedData.current_status === "feedback_done";

if (tracking_locked) {
  return [{
    json: {
      status: "tracking_locked",
      tracking_locked: true,
      message: "Feedback already submitted for this booking. Tracking is complete.",
      booking_id: data.booking_id,
      show_feedback_button: false,
      show_track_button: false
    }
  }];
}

// Pass through for Feedback Processor
return [{
  json: {
    ...data,
    tracking_locked: false
  }
}];
